#!/bin/bash
# Task 087 -- meshsim v1.25 CL1 re-verification (WORKER11): main at ba7a97c (the replayer's queue ports one 1 MB part
# each: code 0x100000, read log 0x200000, write log 0x300000, expansion 0x400000).
#  1. run_tests.sh's quick suite (tools/run_quick.sh, 8 at a time) and its full-mode extras (tools/run_full.sh, 4 at a time);
#  2. the full-size sort p4/uniform-k128 (WORKER8's runner kit, jar rebuilt from main; image, boot ROM, hops unchanged);
#  3. a short acceptance check: the selected windows (/tmp/w9-selected-windows.tgz, SHA-256 c62de022..., WORKER9's
#     report; imm_signed [86]), extracted to scratch, every window of both programs in Stage A, Stage B (tile 0 alone)
#     and Stage F (the full chip), with the acceptance kit's run_shard.sh -n all -x 1.
# The kit (wip/ at Java 17 with every image prebuilt; sortrunner/; w11-kit/) is embedded below, SHA-256 checked;
# smoke-tested locally. Expected ~20 min.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/087-w11-cl1-verify; mkdir -p "$RES"
WANT=dfbb9b9b633816c6387347d422187548639f92932c313021f0f4457bcaf53948
W=/tmp/w11-087; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
cd "$W/wip/meshsim" || exit 2
P=8 ./run_quick.sh "$W/out"; RQ=$?
P=4 ./run_full.sh "$W/out"; RF=$?
cd "$W/sortrunner" || exit 2
printf 'p4/uniform-k128\n' > "$W/p4list"
bash ./run_p4.sh -j 1 -m 6g -l "$W/p4list" "$W/p4"; RS=$?
# the selected windows
RA=0; SEL=/tmp/w9-selected-windows.tgz; SW=c62de0229be30864655e68a1d8cc00bffba4c271027c764a22d7f1580e0c1ca1
GOT=$(sha256sum "$SEL" 2>/dev/null | cut -d' ' -f1)
if [ "$GOT" != "$SW" ]; then echo "selected windows: $SEL sha256 '$GOT', expected $SW"; RA=1
else
  mkdir -p "$W/sel" && tar -xzf "$SEL" -C "$W/sel" || RA=1
  for P in evm-zone-29 cyclone-29; do
    D=$(dirname "$(find "$W/sel" -type d -name "$P" | head -1)")
    MF="$D/$P.manifest.json"; [ -f "$MF" ] || MF="$D/manifest.json"
    echo "== selected windows of $P: $D ($(basename "$MF"))"
    (cd "$W/w11-kit" && ./run_shard.sh -d "$D" -p "$P" -M "$MF" -n all -j 16 -x 1 "$W/sel-out/$P") || RA=1
  done
fi
echo "run_quick.sh exit $RQ, run_full.sh exit $RF, run_p4.sh exit $RS, selected windows exit $RA at $(date -u)"
mkdir -p "$RES/p4" "$RES/selected"; cp "$W"/out/* "$RES/" 2>/dev/null; cp "$W"/p4/* "$RES/p4/" 2>/dev/null; cp -r "$W"/sel-out/* "$RES/selected/" 2>/dev/null
cat "$W/out/VERDICT.txt" "$W/out/FULL-VERDICT.txt" "$W/p4/VERDICT.txt" "$W"/sel-out/*/VERDICT.txt 2>/dev/null
rm -rf "$W"
[ $RQ = 0 ] && [ $RF = 0 ] && [ $RS = 0 ] && [ $RA = 0 ]; exit $?
